def encode(fields):
    return "|".join(
        field.replace("\\", "\\\\").replace("|", "\\|")
        for field in fields
    )


def decode(line):
    fields = []
    current = []
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if c == "|":
            fields.append("".join(current))
            current = []
            i += 1
        elif c == "\\":
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            nxt = line[i + 1]
            if nxt == "\\":
                current.append("\\")
                i += 2
            elif nxt == "|":
                current.append("|")
                i += 2
            else:
                raise ValueError("invalid escape")
        else:
            current.append(c)
            i += 1
    fields.append("".join(current))
    return fields
